/**
 * Docs navigation labels by locale: tab names, group names, sidebar link
 * titles and tutorial time tags, as content/navigation/en.json writes them
 * in English. content/navigation/en/labels.json lists them by the slug of
 * the English label (generated by packages/docs-tooling gen:nav-labels);
 * Lingo translates it to content/navigation/<locale>/labels.json, `{}`
 * until it has. A label without a translation stays English. Page titles
 * come from each page's own (translated) frontmatter instead.
 */
import ar from "@@/content/navigation/ar/labels.json";
import de from "@@/content/navigation/de/labels.json";
import el from "@@/content/navigation/el/labels.json";
import en from "@@/content/navigation/en/labels.json";
import es from "@@/content/navigation/es/labels.json";
import fi from "@@/content/navigation/fi/labels.json";
import fr from "@@/content/navigation/fr/labels.json";
import id from "@@/content/navigation/id/labels.json";
import it from "@@/content/navigation/it/labels.json";
import ja from "@@/content/navigation/ja/labels.json";
import ko from "@@/content/navigation/ko/labels.json";
import nl from "@@/content/navigation/nl/labels.json";
import pl from "@@/content/navigation/pl/labels.json";
import pt from "@@/content/navigation/pt/labels.json";
import ru from "@@/content/navigation/ru/labels.json";
import tr from "@@/content/navigation/tr/labels.json";
import uk from "@@/content/navigation/uk/labels.json";
import vi from "@@/content/navigation/vi/labels.json";
import zh from "@@/content/navigation/zh/labels.json";

/**
 * Slug of an English label, e.g. "Video tutorials" -> "video-tutorials",
 * "~8 min" -> "8-min": the tab keys and the keys of the labels files (the
 * same function as packages/docs-tooling src/generators/nav-labels.ts).
 */
export function labelSlug(s: string): string {
  return (
    s
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "") || "x"
  );
}

export type NavLabelSection = "tabs" | "groups" | "links" | "tags";
type NavLabels = Partial<Record<NavLabelSection, Record<string, string>>>;

const LABELS: Record<string, NavLabels> = {
  ar,
  de,
  el,
  en,
  es,
  fi,
  fr,
  id,
  it,
  ja,
  ko,
  nl,
  pl,
  pt,
  ru,
  tr,
  uk,
  vi,
  zh,
};

/** `english` (a label from navigation/en.json) in `locale`. */
export function navLabel(
  locale: string,
  section: NavLabelSection,
  english: string,
): string;
export function navLabel(
  locale: string,
  section: NavLabelSection,
  english: string | undefined,
): string | undefined;
export function navLabel(
  locale: string,
  section: NavLabelSection,
  english: string | undefined,
): string | undefined {
  if (english === undefined) return undefined;
  const label = LABELS[locale]?.[section]?.[labelSlug(english)];
  return typeof label === "string" && label.trim() ? label : english;
}
